namespace MyApp.Eval;

internal static class EvalConstants
{
    public const string ModelDeployment = "gpt-4o-mini";
    public const string ScenarioName = "CoachChat";
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: captures token usage, latency, and turn count per scenario.
/// </summary>
public class TelemetryTests : IAsyncLifetime
{
    private readonly ReportingConfiguration _reporting;
    private ScenarioRun? _scenarioRun;

    public TelemetryTests()
    {
        var storage = new DiskBasedResultStorage("eval-results/telemetry");
        _reporting = new ReportingConfiguration(
            storage,
            evaluators: [new TokenCountEvaluator()]);
    }

    public async Task InitializeAsync()
    {
        _scenarioRun = await _reporting.CreateScenarioRunAsync(
            EvalConstants.ScenarioName,
            additionalProperties: [new("mode", "telemetry")]);
    }

    public async Task DisposeAsync()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [Fact]
    public async Task Capture_token_usage()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is a good warm-up before running?")
        };

        // In a full integration, the chat client would be resolved from
        // the Aspire AppHost. For eval purposes, record the request/response.
        var response = new ChatMessage(ChatRole.Assistant,
            "A good warm-up includes dynamic stretches like leg swings and light jogging for 5 minutes.");

        _scenarioRun!.Record(messages, response);
        await _scenarioRun.EvaluateAsync();

        var tokenResult = _scenarioRun.GetResult(TokenCountEvaluator.TokenCountMetricName);
        Assert.NotNull(tokenResult);
    }
}

/// <summary>
/// Simple evaluator that counts approximate tokens in the response.
/// </summary>
internal sealed class TokenCountEvaluator : ChatEvaluator
{
    public const string TokenCountMetricName = "TokenCount";

    protected override Task<IReadOnlyList<EvaluationMetric>> EvaluateCoreAsync(
        IEnumerable<ChatMessage> messages,
        ChatMessage modelResponse,
        ChatConfiguration? chatConfiguration,
        IReadOnlyList<EvaluationContext>? additionalContext,
        CancellationToken cancellationToken)
    {
        // Rough approximation: 1 token ≈ 4 characters
        int approxTokens = (modelResponse.Text?.Length ?? 0) / 4;

        var metric = new NumericMetric(TokenCountMetricName, approxTokens);
        IReadOnlyList<EvaluationMetric> result = [metric];
        return Task.FromResult(result);
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: judges response relevance, coherence, and groundedness.
/// </summary>
public class QualityTests : IAsyncLifetime
{
    private readonly ReportingConfiguration _reporting;
    private ScenarioRun? _scenarioRun;

    public QualityTests()
    {
        var storage = new DiskBasedResultStorage("eval-results/quality");
        _reporting = new ReportingConfiguration(
            storage,
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new GroundednessEvaluator()
            ],
            chatConfiguration: GetJudgeChatConfiguration());
    }

    public async Task InitializeAsync()
    {
        _scenarioRun = await _reporting.CreateScenarioRunAsync(
            EvalConstants.ScenarioName,
            additionalProperties: [new("mode", "quality")]);
    }

    public async Task DisposeAsync()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [Fact]
    public async Task Judge_response_quality()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How should I pace a 5K race?")
        };

        var response = new ChatMessage(ChatRole.Assistant,
            "For a 5K, start at a comfortable pace for the first kilometer, " +
            "then gradually increase. Aim for negative splits where each km is " +
            "slightly faster than the last. Save a kick for the final 400m.");

        _scenarioRun!.Record(messages, response);
        await _scenarioRun.EvaluateAsync();

        var relevance = _scenarioRun.GetResult(RelevanceEvaluator.RelevanceMetricName);
        Assert.NotNull(relevance);
    }

    private static ChatConfiguration GetJudgeChatConfiguration()
    {
        // The judge model is configured via environment variable
        // AZURE_OPENAI_ENDPOINT / AZURE_OPENAI_API_KEY at runtime.
        // Returns null configuration when credentials are not available,
        // allowing the evaluator to fall back gracefully.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT");
        if (string.IsNullOrEmpty(endpoint))
            return null!;

        return ChatConfiguration.Default;
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs the same scenario with two model configurations and
/// stores results side-by-side for regression detection.
/// </summary>
public class CompareTests : IAsyncLifetime
{
    private readonly ReportingConfiguration _baselineReporting;
    private readonly ReportingConfiguration _candidateReporting;
    private ScenarioRun? _baselineRun;
    private ScenarioRun? _candidateRun;

    public CompareTests()
    {
        var evaluators = new ChatEvaluator[] { new TokenCountEvaluator() };

        _baselineReporting = new ReportingConfiguration(
            new DiskBasedResultStorage("eval-results/compare/baseline"),
            evaluators: evaluators);

        _candidateReporting = new ReportingConfiguration(
            new DiskBasedResultStorage("eval-results/compare/candidate"),
            evaluators: evaluators);
    }

    public async Task InitializeAsync()
    {
        _baselineRun = await _baselineReporting.CreateScenarioRunAsync(
            EvalConstants.ScenarioName,
            additionalProperties: [new("variant", "baseline")]);

        _candidateRun = await _candidateReporting.CreateScenarioRunAsync(
            EvalConstants.ScenarioName,
            additionalProperties: [new("variant", "candidate")]);
    }

    public async Task DisposeAsync()
    {
        if (_baselineRun is not null)
            await _baselineRun.DisposeAsync();
        if (_candidateRun is not null)
            await _candidateRun.DisposeAsync();
    }

    [Fact]
    public async Task Compare_baseline_vs_candidate()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Suggest a recovery routine after a marathon.")
        };

        // Baseline response (e.g., from current production model)
        var baselineResponse = new ChatMessage(ChatRole.Assistant,
            "Rest for 2-3 days, hydrate well, and do gentle walking.");

        // Candidate response (e.g., from updated prompt or model)
        var candidateResponse = new ChatMessage(ChatRole.Assistant,
            "After a marathon, prioritize sleep and hydration for 48 hours. " +
            "Light foam rolling on day 2, easy 20-min walks on days 2-4, " +
            "then gradually reintroduce easy running by day 5-7.");

        _baselineRun!.Record(messages, baselineResponse);
        await _baselineRun.EvaluateAsync();

        _candidateRun!.Record(messages, candidateResponse);
        await _candidateRun.EvaluateAsync();

        var baselineTokens = _baselineRun.GetResult(TokenCountEvaluator.TokenCountMetricName)
            as NumericMetric;
        var candidateTokens = _candidateRun.GetResult(TokenCountEvaluator.TokenCountMetricName)
            as NumericMetric;

        Assert.NotNull(baselineTokens);
        Assert.NotNull(candidateTokens);

        // Candidate should provide a more detailed response
        Assert.True(candidateTokens.Value >= baselineTokens!.Value,
            "Candidate response should be at least as detailed as baseline.");
    }
}

