    }

    public async Task InitializeAsync()
    {
        _scenarioRun = await _reporting.CreateScenarioRunAsync(
            EvalConstants.ScenarioName,
            additionalProperties: [new("mode", "telemetry")]);
    }

    public async Task DisposeAsync()
    {
        if (_scenarioRun is not null)
            await _scenarioRun.DisposeAsync();
    }

    [Fact]
    public async Task Capture_token_usage()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is a good warm-up before running?")
        };

        // In a full integration, the chat client would be resolved from
        // the Aspire AppHost. For eval purposes, record the request/response.
        var response = new ChatMessage(ChatRole.Assistant,
            "A good warm-up includes dynamic stretches like leg swings and light jogging for 5 minutes.");

        _scenarioRun!.Record(messages, response);
        await _scenarioRun.EvaluateAsync();

        var tokenResult = _scenarioRun.GetResult(TokenCountEvaluator.TokenCountMetricName);
        Assert.NotNull(tokenResult);
    }
}

/// <summary>
/// Simple evaluator that counts approximate tokens in the response.
/// </summary>
internal sealed class TokenCountEvaluator : ChatEvaluator
{
    public const string TokenCountMetricName = "TokenCount";

