        IEnumerable<ChatMessage> messages,
        ChatMessage modelResponse,
        ChatConfiguration? chatConfiguration,
        IReadOnlyList<EvaluationContext>? additionalContext,
        CancellationToken cancellationToken)
    {
        // Rough approximation: 1 token ≈ 4 characters
        int approxTokens = (modelResponse.Text?.Length ?? 0) / 4;

        var metric = new NumericMetric(TokenCountMetricName, approxTokens);
        IReadOnlyList<EvaluationMetric> result = [metric];
        return Task.FromResult(result);
    }
}

